var ITEMS=[["What glaziers do","Glaziers cut, install, and repair glass: windows, storefronts, shower doors, mirrors, and curtain walls. Precision measuring meets careful handling \u2014 glass is unforgiving of mistakes."], ["Essential tools","Glass cutter, straightedge, running pliers, suction cups, glazing knife, heat gun, caulk gun, tape measure, and cut-resistant gloves. Pros add: glass rack for the truck and a water-fed pole for high work."], ["Key skills","Measuring to the 1/16th. Scoring and breaking clean lines. Setting glass plumb and square. Glazing compounds and gaskets. Storefront framing systems. Reading architectural schedules."], ["Safety essentials","Cut-resistant gloves always \u2014 glass edges are razors. Suction cups for large lites; never carry alone what needs two. Eye protection when cutting. Dispose of shards in rigid containers. Ladder and lift safety."], ["Getting started","Start as a helper carrying and cutting; apprenticeships run 3-4 years. Commercial storefront work pays best. Attention to detail is the whole job \u2014 one bad measurement wastes expensive glass."], ["Pro tips","Measure twice, order once \u2014 glass cannot be trimmed much. Score once firmly; re-scoring ruins the break. Keep cutters oiled. Photograph existing conditions. Clean as you go; fingerprints on new glass annoy everyone."], ["Lite","Trade term \u2014 Lite: A single pane of glass."], ["IGU","Trade term \u2014 IGU: Insulated glass unit: sealed double/triple pane."], ["Low-E","Trade term \u2014 Low-E: Low-emissivity coating for energy performance."], ["Tempered glass","Trade term \u2014 Tempered glass: Heat-strengthened safety glass."], ["Laminated glass","Trade term \u2014 Laminated glass: Layers bonded with interlayer; holds when broken."], ["Annealed glass","Trade term \u2014 Annealed glass: Standard float glass."], ["Score","Trade term \u2014 Score: The cut line on glass."], ["Running pliers","Trade term \u2014 Running pliers: Pliers that snap the score."], ["Glazing bead","Trade term \u2014 Glazing bead: The trim holding glass in the frame."], ["Gasket","Trade term \u2014 Gasket: Rubber seal in framing systems."], ["Storefront","Trade term \u2014 Storefront: Commercial aluminum framing system."], ["Curtain wall","Trade term \u2014 Curtain wall: Non-structural glass building skin."], ["Mullion","Trade term \u2014 Mullion: The vertical framing bar."], ["Transom","Trade term \u2014 Transom: The horizontal framing bar."], ["Desiccant","Trade term \u2014 Desiccant: The moisture absorber in IGUs."], ["Seal failure","Trade term \u2014 Seal failure: Foggy IGUs from broken seals."], ["Anneal","Trade term \u2014 Anneal: Slow cooling to relieve glass stress."], ["Cutting oil","Trade term \u2014 Cutting oil: Lubricant for clean scores."], ["Suction cup","Trade term \u2014 Suction cup: The glass handler."]];
function ask(n){var out=[],seen={};n=Math.min(n,ITEMS.length);for(var k=0;k<n;k++){var it=ITEMS[(Math.random()*ITEMS.length)|0];out.push("Q"+(k+1)+": "+it[0]+"\nA"+(k+1)+": "+it[1]);}return out.join("\n\n");}
function lookup(q){q=String(q).toLowerCase();var h=[];for(var i=0;i<ITEMS.length;i++){if((ITEMS[i][0]+" "+ITEMS[i][1]).toLowerCase().indexOf(q)>=0)h.push(ITEMS[i][0]+" — "+ITEMS[i][1]);}return h.length?h.join("\n"):"no match for "+q;}
